// Reads src/data/benchmark.json (generated by scripts/benchmark-data.py). Formatting only; no numbers live here.
import data from "../data/benchmark.json";
import { BENCHMARK_LIVE } from "../data/release";

export const bench = data;
/** Shown in `astro dev` for review, and in production once BENCHMARK_LIVE is on. */
export const showBenchmark = BENCHMARK_LIVE || import.meta.env.DEV;

type ProductId = keyof typeof data.products;
const meta = data.products as Record<string, { name: string; version: string; us?: boolean; previous?: boolean; after_join?: boolean }>;
/** The Connection Guard build the page is about, and the earlier release shown as a reference (from benchmark.json). */
export const CURRENT = (Object.keys(meta).find((p) => meta[p]!.us && !meta[p]!.previous) ?? "connection-guard-candidate") as ProductId;
export const PREVIOUS = (Object.keys(meta).find((p) => meta[p]!.previous) ?? "connection-guard") as ProductId;
/** Lets every player in and checks afterwards (KauriVPN): its login times are not decision times. */
export const afterJoin = (id: string) => Boolean(meta[id]?.after_join);
/** Measured without the shared ProxyCheck key the other plugins' keyless requests got. */
export const unnormalized = new Set<string>(((data.detection as { unnormalized?: string[] }).unnormalized) ?? []);
export const releaseCandidate = /RC|candidate/i.test(meta[CURRENT as string]?.version ?? "");
/** Connection Guard first, then the other plugins in alphabetical order; the previous CG release is a reference only. */
export const COMPARED = (Object.keys(data.products) as ProductId[])
  .filter((p) => p !== PREVIOUS)
  .sort((a, b) => (a === CURRENT ? -1 : b === CURRENT ? 1 : data.products[a].name.localeCompare(data.products[b].name)));

export const product = (id: string) => data.products[id as ProductId];
export const label = (id: string) => id === "none" ? "No anti-VPN plugin" : product(id).name;
export const versionOf = (id: string) => product(id)?.version ?? "";

export function ms(value: number): string {
  if (value >= 10_000) return `${Math.round(value / 1000)} s`;
  if (value >= 1000) return `${(value / 1000).toFixed(1)} s`;
  return `${Math.round(value)} ms`;
}
export const num = (n: number) => n.toLocaleString("en-US");
export const dateLabel = (data as { date_label?: string }).date_label
  ?? new Date(`${data.date}T12:00:00Z`).toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
export const preliminary = data.status !== "published";

type Phase = "cold" | "warm" | "stampede" | "burst";
export const perf = (id: string, phase: Phase) => (data.performance as Record<string, Record<string, any>>)[id]?.[phase] as
  { decision_p50: number; decision_p95: number; join_p50: number; join_p95: number; checked: number; subjects: number; outcomes: Record<string, number> } | undefined;

/** A product that hits the harness deadline (30 s) did not decide in time. */
export const timedOut = (value: number) => value >= 29_000;

export const cohorts = data.detection.cohorts;
export const catchCohorts = cohorts.filter((c) => c.kind === "catch");
export const spareCohorts = cohorts.filter((c) => c.kind === "spare");
export const blocked = (cohortId: string, id: string) => cohorts.find((c) => c.id === cohortId)?.blocked[id as keyof typeof cohorts[number]["blocked"]] ?? 0;
export const spareTotal = (id: string) => spareCohorts.reduce((s, c) => s + (c.blocked as Record<string, number>)[id]!, 0);
export const spareN = spareCohorts.reduce((s, c) => s + c.n, 0);

export const FAULT_LABELS: Record<string, string> = {
  control: "Everything working",
  timeout: "Services time out",
  http_429: "Services rate-limit (429)",
  malformed: "Services send broken answers",
  incomplete: "Services cut answers off",
};
export const failure = data.failure as Record<string, Record<string, Record<string, { blocked: boolean; ms: number; lookups: number }>>>;
